// Every certificate generated by Hakimestan programs and games must credit the designer
// «طراحی و توسعه: مهدی شریفیان» inside the certificate itself (screen, print and image download).
'use strict';

const fs = require('node:fs');
const assert = require('node:assert/strict');
const { JSDOM } = require('jsdom');

const read = (f) => fs.readFileSync(f, 'utf8');
const CREDIT = 'طراحی و توسعه: مهدی شریفیان';

// 1) Shared A4 module (HakimCert) used by hamava, iran-geography, decimals, geometry,
//    measurement, stats and farsi5-vocab: the signature block shows the credit by default.
{
  const dom = new JSDOM('<!doctype html><html><body><div id="c"></div></body></html>', { runScripts: 'outside-only' });
  dom.window.eval(read('js/hakim-cert.js'));
  const HC = dom.window.HakimCert;
  assert.ok(HC && typeof HC.render === 'function', 'HakimCert.render missing');
  const html = HC.render({ name: 'آزمون', program: 'برنامهٔ آزمایشی', achievement: 'x' });
  const box = dom.window.document.createElement('div');
  box.innerHTML = html;
  const dev = box.querySelector('.hk-a4-sign .hk-a4-dev');
  assert.ok(dev, 'HakimCert certificate has no designer credit');
  assert.equal(dev.textContent.trim(), CREDIT);
  assert.ok(/\.hk-a4-sign \.hk-a4-dev\s*\{/.test(read('css/hakim-cert.css')), 'hk-a4-dev style missing');
  for (const f of ['games/farsi5-hamava/app.js', 'games/iran-geography/app.js', 'games/math-decimals/app.js',
    'games/math-geometry/app.js', 'games/math-measurement/app.js', 'games/math-stats/app.js', 'games/farsi5-vocab.html']) {
    const src = read(f);
    assert.match(src, /HakimCert\??\.(mount|render)\(/, f + ' no longer uses HakimCert');
    assert.doesNotMatch(src, /credit\s*:\s*['"`]\s*['"`]/, f + ' blanks the designer credit');
  }
}

// 2) Certificates with their own templates: the credit sits inside the certificate markup.
const inside = [
  ['games/hakim-quest.html', /<div class="cert-line cert-dev">طراحی و توسعه: <b>مهدی شریفیان<\/b>/],
  ['games/math-fasl2.html', /<div class="cert-credit">طراحی و توسعه: <strong>مهدی شریفیان/],
  ['games/math-time-mission.html', /cert-footer[^`]*مهدی شریفیان/],
  ['games/lab2d.html', /<div>طراحی و توسعه<b>مهدی شریفیان<\/b><\/div>/],
  ['games/lab2d-apps/hakim-incline.html', /طراحی و توسعه: مهدی شریفیان/],
  ['games/lab2d-apps/hakim-pulley.html', /طراحی و توسعه: مهدی شریفیان/],
  ['games/kohan-diyar.html', /ctx\.fillText\('طراحی و توسعه: مهدی شریفیان'/],
  ['games/farsi5-vocab.html', /ctx\.fillText\('طراحی و توسعه: مهدی شریفیان'/],
  ['cert-studio.html', /class="c-dev"[^`]*طراحی و توسعه: مهدی شریفیان/],
  ['masir-yadgiri.html', /طراحی و توسعه: مهدی شریفیان/],
];
for (const [f, re] of inside) assert.match(read(f), re, f + ': designer credit missing from the certificate');
for (const f of ['games/math-nesbat.html', 'games/math-olgoha.html', 'games/math-learning-1.html'])
  assert.match(read(f), /مهدی شریفیان/, f + ': designer credit missing');

// 3) The hakim-quest credit is inside #certificate, not only in the page footer.
{
  const doc = new JSDOM(read('games/hakim-quest.html')).window.document;
  const cert = doc.getElementById('certificate');
  assert.ok(cert && cert.textContent.includes('مهدی شریفیان'), 'hakim-quest #certificate lacks the credit');
}

// The legacy templates use the same local stacked logo; achievement badges remain distinct from stamps.
for (const f of ['games/hakim-quest.html','games/kohan-diyar.html','games/lab2d.html',
  'games/math-fasl2.html','games/math-learning-1.html','games/math-nesbat.html',
  'games/math-olgoha.html','games/math-time-mission.html','games/farsi5-vocab.html',
  'games/lab2d-apps/hakim-incline.html','games/lab2d-apps/hakim-pulley.html','masir-yadgiri.html','cert-studio.html']) {
  assert.match(read(f), /hakimestan-logo-stacked\.svg/, f + ': official logo missing');
}
assert.doesNotMatch(read('masir-yadgiri.html'), /W\.(seal|signature)\(/, 'grand certificate must not use a seal or handwritten signature');
assert.doesNotMatch(read('js/hakim-worlds.js'), /M8 32c14-22 22-26/, 'handwritten signature removed');
assert.doesNotMatch(read('games/kohan-diyar.html'), /ctx\.fillText\('مهر'/, 'legacy PNG seal removed');
console.log('cert-credit: all certificate generators credit the designer and legacy certificates use the official logo ✓');
